# 基于端侧AI体态识别的穿戴隐私安全防护系统 — 实现方案

## 一、整体架构设计

### 1.1 系统架构图

```
┌─────────────────────────────────────────────────────────────────┐
│                    OpenVela 智能手表快应用                        │
├─────────────────────────────────────────────────────────────────┤
│  UI 层 (快应用页面)                                              │
│  ┌──────────┐ ┌──────────┐ ┌──────────┐ ┌──────────┐           │
│  │ 首页总览  │ │ 体态监测  │ │ 数据安全  │ │ 报表统计  │           │
│  │  index   │ │ posture  │ │ security │ │ report   │           │
│  └──────────┘ └──────────┘ └──────────┘ └──────────┘           │
├─────────────────────────────────────────────────────────────────┤
│  业务逻辑层                                                      │
│  ┌──────────────┐ ┌──────────────┐ ┌──────────────┐            │
│  │ 体态识别引擎  │ │ 数据脱敏引擎  │ │ 加密存储引擎  │            │
│  │ posture.js   │ │ sanitizer.js │ │ crypto.js    │            │
│  └──────────────┘ └──────────────┘ └──────────────┘            │
├─────────────────────────────────────────────────────────────────┤
│  服务层                                                          │
│  ┌──────────────┐ ┌──────────────┐ ┌──────────────┐            │
│  │ 传感器采集    │ │ 健康数据SDK  │ │ 本地文件存储  │            │
│  │ @sensor      │ │ @health      │ │ @file        │            │
│  └──────────────┘ └──────────────┘ └──────────────┘            │
├─────────────────────────────────────────────────────────────────┤
│  硬件层: 加速度传感器 / 陀螺仪 / 心率传感器 / 本地存储 / 屏幕     │
└─────────────────────────────────────────────────────────────────┘
```

### 1.2 数据流设计

```
传感器采集 → 原始时序数据 → AI体态识别 → 体态状态判定
    ↓                                    ↓
心率/步数采集 → 原始隐私数据 → 脱敏处理 → 脱敏后数据
                                         ↓
                              分级加密存储 ← 定时销毁策略
                                         ↓
                              安全可视化展示 → 用户交互
```

### 1.3 技术选型

| 模块 | 技术方案 | 说明 |
|------|----------|------|
| UI框架 | OpenVela 快应用框架 | `.ux` 单文件组件 |
| 传感器 | `@system.sensor` | 加速度+陀螺仪采集 |
| 健康数据 | `@system.health` | 心率、步数读取 |
| 本地存储 | `@system.file` + `@system.storage` | 文件存储+KV存储 |
| AI推理 | 阈值分类+特征提取 | 轻量化，无需模型文件 |
| 加密 | AES-128 纯JS实现 | 分级密钥管理 |
| 定时任务 | `@system.timer` | 数据过期销毁 |

---

## 二、目录结构设计

```
src/
├── app.ux                          # 应用入口
├── manifest.json                   # 应用配置(需更新features)
├── common/
│   ├── logo.png                    # 应用图标
│   ├── constants.js                # 全局常量(阈值、密钥标识等)
│   └── utils.js                    # 通用工具函数
├── services/
│   ├── sensor-service.js           # 传感器数据采集与Mock管理
│   ├── health-service.js           # 健康数据读取(心率/步数)
│   ├── posture-engine.js           # 体态识别AI引擎
│   ├── sanitizer.js                # 数据脱敏引擎
│   ├── crypto-engine.js            # AES分级加密引擎
│   └── storage-service.js          # 加密存储+自动销毁管理
├── components/
│   ├── status-card.ux              # 状态卡片组件(通用)
│   ├── chart-bar.ux                # 柱状图组件
│   ├── toggle-switch.ux            # 开关组件
│   └── data-compare.ux             # 数据加密前后对比组件
├── pages/
│   ├── index/
│   │   └── index.ux                # 首页: 总览+快捷入口
│   ├── posture/
│   │   └── posture.ux              # 体态监测页: 实时识别+提醒
│   ├── security/
│   │   └── security.ux             # 数据安全页: 脱敏+加密状态
│   └── report/
│       └── report.ux               # 报表页: 每日统计+健康评分
└── i18n/
    ├── zh-CN.json
    ├── en.json
    └── defaults.json
```

---

## 三、各功能详细实现方案

### 功能1: 端侧AI多场景不良体态智能识别与矫正提醒

#### 3.1.1 传感器采集模块 — `services/sensor-service.js`

```javascript
/**
 * 传感器数据采集服务
 * 负责加速度/陀螺仪数据采集、Mock数据生成、滑动窗口管理
 */
import sensor from '@system.sensor'

class SensorService {
  constructor() {
    this.accelData = []        // 加速度时序数据缓冲
    this.gyroData = []         // 陀螺仪时序数据缓冲
    this.windowSize = 50       // 滑动窗口大小(50个采样点)
    this.isRunning = false
    this.mockMode = true       // 模拟器默认使用Mock模式
  }

  // 启动传感器采集
  start(callback) {
    this.isRunning = true
    if (this.mockMode) {
      this._startMockStream(callback)
    } else {
      this._startRealSensor(callback)
    }
  }

  // Mock数据流 — 模拟各类体态场景
  _startMockStream(callback) {
    // 使用定时器模拟传感器采样频率(约20Hz)
    this._mockTimer = setInterval(() => {
      const mockSample = this._generateMockSample()
      this._appendToWindow(mockSample)
      if (callback) callback(this.getLatestFeatures())
    }, 50) // 50ms = 20Hz
  }

  // 生成Mock传感器样本(基于正弦波+噪声模拟)
  _generateMockSample() {
    const t = Date.now() / 1000
    // 基础重力 + 微小波动模拟手腕静止/运动
    return {
      timestamp: Date.now(),
      accel: {
        x: 0.1 * Math.sin(t * 2) + (Math.random() - 0.5) * 0.05,
        y: 9.8 + 0.1 * Math.cos(t * 1.5) + (Math.random() - 0.5) * 0.05,
        z: 0.05 * Math.sin(t * 3) + (Math.random() - 0.5) * 0.03
      },
      gyro: {
        x: 0.02 * Math.sin(t * 4) + (Math.random() - 0.5) * 0.01,
        y: 0.01 * Math.cos(t * 3) + (Math.random() - 0.5) * 0.01,
        z: 0.015 * Math.sin(t * 5) + (Math.random() - 0.5) * 0.008
      }
    }
  }

  // 模拟特定不良体态场景数据
  generateScenarioData(scenario) {
    const scenarios = {
      sedentary:    this._mockSedentary(),    // 久坐伏案
      headDown:     this._mockHeadDown(),      // 低头前倾
      crossLeg:     this._mockCrossLeg(),      // 跷二郎腿
      normal:       this._mockNormal()         // 正常坐姿
    }
    return scenarios[scenario] || scenarios.normal
  }

  _mockSedentary() {
    // 久坐: 加速度Y轴偏移(前倾), 陀螺仪几乎静止
    return Array.from({ length: 50 }, (_, i) => ({
      timestamp: Date.now() - (50 - i) * 50,
      accel: { x: 0.3, y: 8.5, z: 0.1 },   // Y轴偏低=前倾
      gyro: { x: 0.001, y: 0.001, z: 0.001 }
    }))
  }

  _mockHeadDown() {
    // 低头: Z轴显著偏移, 俯仰角变化
    return Array.from({ length: 50 }, (_, i) => ({
      timestamp: Date.now() - (50 - i) * 50,
      accel: { x: 0.5, y: 7.0, z: 1.5 },   // Z轴偏高=低头
      gyro: { x: 0.03, y: 0.001, z: 0.001 }
    }))
  }

  _mockCrossLeg() {
    // 跷二郎腿: X轴周期性摆动
    return Array.from({ length: 50 }, (_, i) => ({
      timestamp: Date.now() - (50 - i) * 50,
      accel: {
        x: 0.8 * Math.sin(i * 0.3),
        y: 9.5,
        z: 0.2 * Math.cos(i * 0.3)
      },
      gyro: { x: 0.01, y: 0.02, z: 0.005 }
    }))
  }

  _mockNormal() {
    return Array.from({ length: 50 }, (_, i) => ({
      timestamp: Date.now() - (50 - i) * 50,
      accel: { x: 0.05, y: 9.7, z: 0.02 },
      gyro: { x: 0.002, y: 0.001, z: 0.001 }
    }))
  }

  // 滑动窗口管理
  _appendToWindow(sample) {
    this.accelData.push(sample.accel)
    this.gyroData.push(sample.gyro)
    if (this.accelData.length > this.windowSize) {
      this.accelData.shift()
      this.gyroData.shift()
    }
  }

  // 提取窗口内特征值(供AI引擎使用)
  getLatestFeatures() {
    if (this.accelData.length < 10) return null
    return {
      accelMean: this._mean(this.accelData),
      accelStd: this._std(this.accelData),
      gyroMean: this._mean(this.gyroData),
      gyroStd: this._std(this.gyroData),
      pitchAngle: this._calcPitch(),
      rollAngle: this._calcRoll(),
      movementIntensity: this._calcIntensity(),
      sampleCount: this.accelData.length
    }
  }

  _mean(data) {
    const axes = ['x', 'y', 'z']
    const result = {}
    axes.forEach(axis => {
      result[axis] = data.reduce((s, d) => s + d[axis], 0) / data.length
    })
    return result
  }

  _std(data) {
    const axes = ['x', 'y', 'z']
    const mean = this._mean(data)
    const result = {}
    axes.forEach(axis => {
      const variance = data.reduce((s, d) => s + Math.pow(d[axis] - mean[axis], 2), 0) / data.length
      result[axis] = Math.sqrt(variance)
    })
    return result
  }

  _calcPitch() {
    const latest = this.accelData[this.accelData.length - 1]
    if (!latest) return 0
    return Math.atan2(latest.y, Math.sqrt(latest.x * latest.x + latest.z * latest.z)) * 180 / Math.PI
  }

  _calcRoll() {
    const latest = this.accelData[this.accelData.length - 1]
    if (!latest) return 0
    return Math.atan2(latest.x, latest.y) * 180 / Math.PI
  }

  _calcIntensity() {
    if (this.accelData.length < 2) return 0
    let totalDelta = 0
    for (let i = 1; i < this.accelData.length; i++) {
      const dx = this.accelData[i].x - this.accelData[i-1].x
      const dy = this.accelData[i].y - this.accelData[i-1].y
      const dz = this.accelData[i].z - this.accelData[i-1].z
      totalDelta += Math.sqrt(dx*dx + dy*dy + dz*dz)
    }
    return totalDelta / (this.accelData.length - 1)
  }

  stop() {
    this.isRunning = false
    if (this._mockTimer) clearInterval(this._mockTimer)
  }
}

export default new SensorService()
```

#### 3.1.2 体态识别AI引擎 — `services/posture-engine.js`

```javascript
/**
 * 体态识别AI引擎
 * 基于阈值分类的轻量化算法，识别久坐、低头、跷二郎腿等不良体态
 */
import sensorService from './sensor-service'
import storage from '@system.storage'

// 体态判定阈值配置
const THRESHOLDS = {
  sedentary: {
    pitchMin: 15,           // 前倾角度阈值(度)
    gyroThreshold: 0.005,   // 陀螺仪变化阈值(静止判定)
    duration: 300000        // 持续时间阈值(5分钟=久坐)
  },
  headDown: {
    pitchMin: 30,           // 低头角度阈值
    zAccelMin: 1.0,         // Z轴加速度阈值
    duration: 120000        // 持续时间阈值(2分钟)
  },
  crossLeg: {
    xOscillationMin: 0.5,   // X轴摆动幅度阈值
    frequencyMin: 0.5,      // 最低摆动频率(Hz)
    duration: 60000          // 持续时间阈值(1分钟)
  }
}

// 体态类型枚举
export const POSTURE_TYPES = {
  NORMAL: 'normal',
  SEDENTARY: 'sedentary',
  HEAD_DOWN: 'headDown',
  CROSS_LEG: 'crossLeg'
}

// 体态状态描述
export const POSTURE_LABELS = {
  [POSTURE_TYPES.NORMAL]: { zh: '正常坐姿', icon: '✓', color: '#4CAF50' },
  [POSTURE_TYPES.SEDENTARY]: { zh: '久坐伏案', icon: '⚠', color: '#FF9800' },
  [POSTURE_TYPES.HEAD_DOWN]: { zh: '低头前倾', icon: '⚠', color: '#F44336' },
  [POSTURE_TYPES.CROSS_LEG]: { zh: '跷二郎腿', icon: '⚠', color: '#FF5722' }
}

class PostureEngine {
  constructor() {
    this.currentPosture = POSTURE_TYPES.NORMAL
    this.postureStartTime = Date.now()
    this.dailyStats = {
      [POSTURE_TYPES.SEDENTARY]: 0,
      [POSTURE_TYPES.HEAD_DOWN]: 0,
      [POSTURE_TYPES.CROSS_LEG]: 0,
      totalAbnormal: 0
    }
    this.alertCallbacks = []
    this._loadDailyStats()
  }

  // 注册提醒回调
  onAlert(callback) {
    this.alertCallbacks.push(callback)
  }

  // 核心识别方法: 输入特征 → 输出体态类型
  classify(features) {
    if (!features) return POSTURE_TYPES.NORMAL

    const newPosture = this._classifyByFeatures(features)

    // 状态切换检测 → 触发提醒
    if (newPosture !== this.currentPosture) {
      if (newPosture !== POSTURE_TYPES.NORMAL) {
        // 进入不良体态, 记录开始时间
        this.postureStartTime = Date.now()
      } else {
        // 恢复正常, 记录不良体态持续时长
        const duration = Date.now() - this.postureStartTime
        if (duration > 30000) { // 超过30秒才计入统计
          this.dailyStats[this.currentPosture]++
          this.dailyStats.totalAbnormal++
          this._saveDailyStats()
        }
      }
      this.currentPosture = newPosture
      this._notifyAlert(newPosture)
    }

    return {
      type: this.currentPosture,
      label: POSTURE_LABELS[this.currentPosture],
      duration: Date.now() - this.postureStartTime,
      dailyStats: { ...this.dailyStats }
    }
  }

  _classifyByFeatures(f) {
    // 1. 低头判定: 俯仰角大 + Z轴加速度高
    if (f.pitchAngle > THRESHOLDS.headDown.pitchMin &&
        f.accelMean.z > THRESHOLDS.headDown.zAccelMin) {
      return POSTURE_TYPES.HEAD_DOWN
    }

    // 2. 久坐伏案: 俯仰角中等 + 陀螺仪几乎静止(无运动)
    const gyroMovement = Math.abs(f.gyroMean.x) + Math.abs(f.gyroMean.y) + Math.abs(f.gyroMean.z)
    if (f.pitchAngle > THRESHOLDS.sedentary.pitchMin &&
        gyroMovement < THRESHOLDS.sedentary.gyroThreshold) {
      return POSTURE_TYPES.SEDENTARY
    }

    // 3. 跷二郎腿: X轴周期性摆动
    if (f.accelStd.x > THRESHOLDS.crossLeg.xOscillationMin &&
        f.movementIntensity > 0.1) {
      return POSTURE_TYPES.CROSS_LEG
    }

    return POSTURE_TYPES.NORMAL
  }

  _notifyAlert(posture) {
    this.alertCallbacks.forEach(cb => cb(posture, POSTURE_LABELS[posture]))
  }

  // 获取每日健康评分(0-100)
  getHealthScore() {
    const total = this.dailyStats.totalAbnormal
    // 基础分100, 每次异常扣5分, 最低0分
    return Math.max(0, 100 - total * 5)
  }

  // 持久化每日统计
  _saveDailyStats() {
    const today = new Date().toISOString().slice(0, 10)
    storage.set({
      key: `posture_stats_${today}`,
      value: JSON.stringify(this.dailyStats)
    })
  }

  _loadDailyStats() {
    const today = new Date().toISOString().slice(0, 10)
    storage.get({
      key: `posture_stats_${today}`,
      success: (data) => {
        if (data) this.dailyStats = JSON.parse(data)
      }
    })
  }

  // 重置每日统计(跨天调用)
  resetDaily() {
    this.dailyStats = {
      [POSTURE_TYPES.SEDENTARY]: 0,
      [POSTURE_TYPES.HEAD_DOWN]: 0,
      [POSTURE_TYPES.CROSS_LEG]: 0,
      totalAbnormal: 0
    }
  }
}

export default new PostureEngine()
