### 功能2: 穿戴传感与健康数据本地智能脱敏处理

#### 3.2.1 数据脱敏引擎 — `services/sanitizer.js`

```javascript
/**
 * 数据脱敏引擎
 * 对健康体态数据进行字段级脱敏、匿名化处理
 * 保留体态分析有效特征，隐藏精准时间/坐标/生理峰值
 */

// 脱敏规则配置
const SANITIZE_RULES = {
  // 精确时间戳 → 模糊化(保留小时粒度)
  timestamp: {
    type: 'fuzzify',
    precision: 'hour', // 保留到小时, 丢弃分钟/秒
    apply: (val) => {
      const d = new Date(val)
      d.setMinutes(0, 0, 0)
      return d.getTime()
    }
  },

  // 运动轨迹坐标 → 区域化(保留城市级精度)
  coordinates: {
    type: 'area',
    precision: 2, // 保留小数点后2位(约1km精度)
    apply: (lat, lng) => ({
      lat: Math.round(lat * 100) / 100,
      lng: Math.round(lng * 100) / 100
    })
  },

  // 心率值 → 范围化(不暴露精确值)
  heartRate: {
    type: 'range',
    ranges: [
      { min: 0, max: 60, label: 'low' },
      { min: 60, max: 100, label: 'normal' },
      { min: 100, max: 150, label: 'medium' },
      { min: 150, max: 255, label: 'high' }
    ],
    apply: (val) => {
      for (const r of this.ranges) {
        if (val >= r.min && val < r.max) return r.label
      }
      return 'unknown'
    }
  },

  // 步数 → 模糊化(保留百位精度)
  steps: {
    type: 'fuzzify',
    apply: (val) => Math.floor(val / 100) * 100
  },

  // 用户身份标识 → 匿名化哈希
  userId: {
    type: 'hash',
    apply: (val) => simpleHash(val)
  }
}

// 简单哈希函数(适合嵌入式环境)
function simpleHash(str) {
  let hash = 0
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i)
    hash |= 0
  }
  return 'anon_' + Math.abs(hash).toString(16)
}

class Sanitizer {
  /**
   * 脱敏处理单条记录
   * @param {Object} rawData - 原始传感器/健康数据
   * @param {Array} fields - 需要脱敏的字段列表
   * @returns {Object} 脱敏后的数据(保留有效特征)
   */
  sanitizeRecord(rawData, fields) {
    const sanitized = { ...rawData }

    fields.forEach(field => {
      const rule = SANITIZE_RULES[field]
      if (rule && rawData[field] !== undefined) {
        sanitized[field] = rule.apply(rawData[field])
      }
    })

    // 添加脱敏标记
    sanitized._sanitized = true
    sanitized._sanitizedAt = Date.now()
    sanitized._sanitizeVersion = '1.0'

    return sanitized
  }

  /**
   * 批量脱敏处理
   * @param {Array} records - 原始数据记录数组
   * @returns {Array} 脱敏后的记录数组
   */
  sanitizeBatch(records) {
    const fields = Object.keys(SANITIZE_RULES)
    return records.map(r => this.sanitizeRecord(r, fields))
  }

  /**
   * 体态数据专用脱敏
   * 只保留体态分析有效特征, 删除所有隐私字段
   */
  sanitizePostureData(rawPostureData) {
    return {
      // 保留: 体态类型、持续时长、健康评分(分析有效)
      postureType: rawPostureData.type,
      duration: rawPostureData.duration,
      healthScore: rawPostureData.healthScore,
      // 脱敏: 时间(小时粒度)
      hour: SANITIZE_RULES.timestamp.apply(rawPostureData.timestamp),
      // 删除: 原始传感器数据、用户ID、精确时间戳
      _sanitized: true
    }
  }

  /**
   * 心率数据脱敏 — 仅保留区间标签
   */
  sanitizeHeartRate(rawHR) {
    return {
      range: SANITIZE_RULES.heartRate.apply(rawHR.value),
      hour: SANITIZE_RULES.timestamp.apply(rawHR.timestamp),
      _sanitized: true
    }
  }

  /**
   * 运动数据脱敏 — 坐标区域化+步数模糊化
   */
  sanitizeMotionData(rawMotion) {
    return {
      area: SANITIZE_RULES.coordinates.apply(
        rawMotion.latitude,
        rawMotion.longitude
      ),
      stepsApprox: SANITIZE_RULES.steps.apply(rawMotion.steps),
      hour: SANITIZE_RULES.timestamp.apply(rawMotion.timestamp),
      _sanitized: true
    }
  }

  /**
   * 验证数据是否已脱敏
   */
  isSanitized(data) {
    return data._sanitized === true
  }

  /**
   * 获取脱敏报告(用于可视化展示)
   */
  getSanitizationReport(rawData, sanitizedData) {
    const fields = Object.keys(rawData)
    const report = {
      totalFields: fields.length,
      sanitizedFields: 0,
      removedFields: 0,
      details: []
    }

    fields.forEach(field => {
      if (field.startsWith('_')) return
      const raw = rawData[field]
      const clean = sanitizedData[field]

      if (clean === undefined) {
        report.removedFields++
        report.details.push({ field, action: 'removed' })
      } else if (JSON.stringify(raw) !== JSON.stringify(clean)) {
        report.sanitizedFields++
        report.details.push({ field, action: 'sanitized' })
      } else {
        report.details.push({ field, action: 'kept' })
      }
    })

    return report
  }
}

export default new Sanitizer()
