### 功能3: 轻量化AES分级加密本地存储

#### 3.3.1 AES加密引擎 — `services/crypto-engine.js`

```javascript
/**
 * 轻量化AES分级加密引擎
 * - 分级密钥: 普通统计数据 / 核心生理隐私数据 使用不同密钥
 * - AES-128-ECB 纯JS实现(适合嵌入式环境)
 * - 支持数据生命周期管理与自动过期销毁
 */

// === AES-128 核心实现 ===
// S-Box
const SBOX = [
  0x63,0x7c,0x77,0x7b,0xf2,0x6b,0x6f,0xc5,0x30,0x01,0x67,0x2b,0xfe,0xd7,0xab,0x76,
  0xca,0x82,0xc9,0x7d,0xfa,0x59,0x47,0xf0,0xad,0xd4,0xa2,0xaf,0x9c,0xa4,0x72,0xc0,
  0xb7,0xfd,0x93,0x26,0x36,0x3f,0xf7,0xcc,0x34,0xa5,0xe5,0xf1,0x71,0xd8,0x31,0x15,
  0x04,0xc7,0x23,0xc3,0x18,0x96,0x05,0x9a,0x07,0x12,0x80,0xe2,0xeb,0x27,0xb2,0x75,
  0x09,0x83,0x2c,0x1a,0x1b,0x6e,0x5a,0xa0,0x52,0x3b,0xd6,0xb3,0x29,0xe3,0x2f,0x84,
  0x53,0xd1,0x00,0xed,0x20,0xfc,0xb1,0x5b,0x6a,0xcb,0xbe,0x39,0x4a,0x4c,0x58,0xcf,
  0xd0,0xef,0xaa,0xfb,0x43,0x4d,0x33,0x85,0x45,0xf9,0x02,0x7f,0x50,0x3c,0x9f,0xa8,
  0x51,0xa3,0x40,0x8f,0x92,0x9d,0x38,0xf5,0xbc,0xb6,0xda,0x21,0x10,0xff,0xf3,0xd2,
  0xcd,0x0c,0x13,0xec,0x5f,0x97,0x44,0x17,0xc4,0xa7,0x7e,0x3d,0x64,0x5d,0x19,0x73,
  0x60,0x81,0x4f,0xdc,0x22,0x2a,0x90,0x88,0x46,0xee,0xb8,0x14,0xde,0x5e,0x0b,0xdb,
  0xe0,0x32,0x3a,0x0a,0x49,0x06,0x24,0x5c,0xc2,0xd3,0xac,0x62,0x91,0x95,0xe4,0x79,
  0xe7,0xc8,0x37,0x6d,0x8d,0xd5,0x4e,0xa9,0x6c,0x56,0xf4,0xea,0x65,0x7a,0xae,0x08,
  0xba,0x78,0x25,0x2e,0x1c,0xa6,0xb4,0xc6,0xe8,0xdd,0x74,0x1f,0x4b,0xbd,0x8b,0x8a,
  0x70,0x3e,0xb5,0x66,0x48,0x03,0xf6,0x0e,0x61,0x35,0x57,0xb9,0x86,0xc1,0x1d,0x9e,
  0xe1,0xf8,0x98,0x11,0x69,0xd9,0x8e,0x94,0x9b,0x1e,0x87,0xe9,0xce,0x55,0x28,0xdf,
  0x8c,0xa1,0x89,0x0d,0xbf,0xe6,0x42,0x68,0x41,0x99,0x2d,0x0f,0xb0,0x54,0xbb,0x16
]

// Rcon
const RCON = [0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1b,0x36]

class AES128 {
  constructor(key) {
    this.key = this._toBytes(key)
    this.roundKeys = this._keyExpansion(this.key)
  }

  _toBytes(hex) {
    const bytes = []
    for (let i = 0; i < hex.length; i += 2) {
      bytes.push(parseInt(hex.substr(i, 2), 16))
    }
    return bytes
  }

  _keyExpansion(key) {
    const nk = 4, nb = 4, nr = 10
    const w = new Array(nb * (nr + 1))

    for (let i = 0; i < nk; i++) {
      w[i] = [key[4*i], key[4*i+1], key[4*i+2], key[4*i+3]]
    }

    for (let i = nk; i < nb * (nr + 1); i++) {
      let temp = [...w[i-1]]
      if (i % nk === 0) {
        temp = this._subWord(this._rotWord(temp))
        temp[0] ^= RCON[i/nk - 1]
      }
      w[i] = [
        w[i-nk][0] ^ temp[0],
        w[i-nk][1] ^ temp[1],
        w[i-nk][2] ^ temp[2],
        w[i-nk][3] ^ temp[3]
      ]
    }
    return w
  }

  _rotWord(w) {
    return [w[1], w[2], w[3], w[0]]
  }

  _subWord(w) {
    return w.map(b => SBOX[b])
  }

  // 加密一个16字节块
  encryptBlock(block) {
    const state = block.slice()
    const nr = 10

    // AddRoundKey(0)
    this._addRoundKey(state, 0)

    for (let round = 1; round < nr; round++) {
      this._subBytes(state)
      this._shiftRows(state)
      this._mixColumns(state)
      this._addRoundKey(state, round)
    }

    this._subBytes(state)
    this._shiftRows(state)
    this._addRoundKey(state, nr)

    return state
  }

  _addRoundKey(state, round) {
    for (let i = 0; i < 16; i++) {
      state[i] ^= this.roundKeys[round * 4 + Math.floor(i/4)][i % 4]
    }
  }

  _subBytes(state) {
    for (let i = 0; i < 16; i++) state[i] = SBOX[state[i]]
  }

  _shiftRows(state) {
    let temp
    // Row 1: shift left 1
    temp = state[1]; state[1] = state[5]; state[5] = state[9]; state[9] = state[13]; state[13] = temp
    // Row 2: shift left 2
    temp = state[2]; state[2] = state[10]; state[10] = temp
    temp = state[6]; state[6] = state[14]; state[14] = temp
    // Row 3: shift left 3
    temp = state[15]; state[15] = state[11]; state[11] = state[7]; state[7] = state[3]; state[3] = temp
  }

  _mixColumns(state) {
    for (let c = 0; c < 4; c++) {
      const i = c * 4
      const a = state[i], b = state[i+1], d = state[i+2], e = state[i+3]
      state[i]   = this._gmul(a,2) ^ this._gmul(b,3) ^ d ^ e
      state[i+1] = a ^ this._gmul(b,2) ^ this._gmul(d,3) ^ e
      state[i+2] = a ^ b ^ this._gmul(d,2) ^ this._gmul(e,3)
      state[i+3] = this._gmul(a,3) ^ b ^ d ^ this._gmul(e,2)
    }
  }

  _gmul(a, b) {
    let p = 0
    for (let i = 0; i < 8; i++) {
      if (b & 1) p ^= a
      const hi = a & 0x80
      a = (a << 1) & 0xff
      if (hi) a ^= 0x1b
      b >>= 1
    }
    return p
  }

  // PKCS7填充
  pad(data) {
    const padLen = 16 - (data.length % 16)
    return [...data, ...Array(padLen).fill(padLen)]
  }

  // 加密任意长度数据(分块)
  encrypt(plaintext) {
    const bytes = typeof plaintext === 'string'
      ? Array.from(plaintext).map(c => c.charCodeAt(0))
      : plaintext

    const padded = this.pad(bytes)
    const ciphertext = []

    for (let i = 0; i < padded.length; i += 16) {
      const block = padded.slice(i, i + 16)
      ciphertext.push(...this.encryptBlock(block))
    }

    return ciphertext.map(b => b.toString(16).padStart(2, '0')).join('')
  }
}

// === 分级密钥管理 ===
const KEY_LEVELS = {
  // 普通统计数据密钥(体态次数、步数统计等)
  NORMAL: 'a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6',
  // 核心生理隐私密钥(心率、加速度原始数据等)
  SENSITIVE: 'f0e1d2c3b4a5968778695a4b3c2d1e0f'
}

class CryptoEngine {
  constructor() {
    this.normalAES = new AES128(KEY_LEVELS.NORMAL)
    this.sensitiveAES = new AES128(KEY_LEVELS.SENSITIVE)
  }

  /**
   * 分级加密
   * @param {string} data - 待加密数据(JSON字符串)
   * @param {string} level - 'normal' | 'sensitive'
   * @returns {string} 十六进制密文
   */
  encrypt(data, level = 'normal') {
    const aes = level === 'sensitive' ? this.sensitiveAES : this.normalAES
    return aes.encrypt(data)
  }

  /**
   * 获取加密元数据(用于存储时附加)
   */
  getEncryptMeta(level) {
    return {
      algorithm: 'AES-128-ECB',
      level: level,
      version: '1.0',
      encryptedAt: Date.now()
    }
  }
}

export default new CryptoEngine()
```

#### 3.3.2 加密存储服务 — `services/storage-service.js`

```javascript
/**
 * 加密存储服务
 * - 分级加密写入本地文件
 * - 数据生命周期管理
 * - 定时自动过期销毁
 */
import storage from '@system.storage'
import cryptoEngine from './crypto-engine'

// 数据保留策略(毫秒)
const RETENTION_POLICY = {
  posture: 7 * 24 * 60 * 60 * 1000,    // 体态数据: 7天
  heartRate: 3 * 24 * 60 * 60 * 1000,   // 心率数据: 3天
  motion: 1 * 24 * 60 * 60 * 1000,      // 运动数据: 1天
  securityLog: 14 * 24 * 60 * 60 * 1000 // 安全日志: 14天
}

class StorageService {
  constructor() {
    this._cleanupTimer = null
  }

  /**
   * 加密并存储数据
   * @param {string} key - 存储键名
   * @param {Object} data - 原始数据对象
   * @param {string} level - 加密级别 'normal' | 'sensitive'
   * @param {string} dataType - 数据类型(用于过期策略)
   */
  saveEncrypted(key, data, level = 'normal', dataType = 'posture') {
    const plaintext = JSON.stringify(data)
    const ciphertext = cryptoEngine.encrypt(plaintext, level)
    const meta = cryptoEngine.getEncryptMeta(level)

    const storageEntry = {
      data: ciphertext,
      meta: meta,
      dataType: dataType,
      expiresAt: Date.now() + (RETENTION_POLICY[dataType] || RETENTION_POLICY.posture)
    }

    storage.set({
      key: `enc_${key}`,
      value: JSON.stringify(storageEntry),
      success: () => console.log(`[Storage] Encrypted save: ${key}`),
      fail: (err) => console.error(`[Storage] Save failed: ${key}`, err)
    })
  }

  /**
   * 读取并解密数据(当前AES实现仅加密,读取时返回密文+元数据)
   * 注: 完整解密需实现AES解密,此处返回存储结构供UI层使用
   */
  loadEncrypted(key, callback) {
    storage.get({
      key: `enc_${key}`,
      success: (data) => {
        if (data) {
          const entry = JSON.parse(data)
          // 检查是否过期
          if (entry.expiresAt && Date.now() > entry.expiresAt) {
            this.delete(key)
            callback && callback(null, 'expired')
            return
          }
          callback && callback(entry)
        } else {
          callback && callback(null, 'not_found')
        }
      },
      fail: (err) => callback && callback(null, err)
    })
  }

  /**
   * 删除指定数据
   */
  delete(key) {
    storage.delete({ key: `enc_${key}` })
  }

  /**
   * 启动自动清理定时器
   * 每小时检查一次过期数据
   */
  startAutoCleanup() {
    this._cleanupTimer = setInterval(() => {
      this._cleanupExpired()
    }, 3600 * 1000) // 每小时
  }

  _cleanupExpired() {
    storage.keys({
      success: (keys) => {
        keys.forEach(key => {
          if (!key.startsWith('enc_')) return
          storage.get({
            key: key,
            success: (data) => {
              if (data) {
                const entry = JSON.parse(data)
                if (entry.expiresAt && Date.now() > entry.expiresAt) {
                  storage.delete({ key: key })
                  console.log(`[Storage] Auto-cleaned expired: ${key}`)
                }
              }
            }
          })
        })
      }
    })
  }

  /**
   * 获取存储状态报告(用于安全可视化)
   */
  getStorageReport(callback) {
    storage.keys({
      success: (keys) => {
        const encKeys = keys.filter(k => k.startsWith('enc_'))
        let totalSize = 0
        let expiredCount = 0
        const typeCounts = {}

        let processed = 0
        if (encKeys.length === 0) {
          callback({ totalFiles: 0, totalSize: 0, expiredCount: 0, typeCounts: {} })
          return
        }

        encKeys.forEach(key => {
          storage.get({
            key: key,
            success: (data) => {
              processed++
              if (data) {
                totalSize += data.length * 2 // 粗略估算字节数
                const entry = JSON.parse(data)
                if (entry.expiresAt && Date.now() > entry.expiresAt) expiredCount++
                const type = entry.dataType || 'unknown'
                typeCounts[type] = (typeCounts[type] || 0) + 1
              }
              if (processed === encKeys.length) {
                callback({
                  totalFiles: encKeys.length,
                  totalSize,
                  expiredCount,
                  typeCounts,
                  encryptionLevels: ['normal', 'sensitive']
                })
              }
            }
          })
        })
      }
    })
  }

  stop() {
    if (this._cleanupTimer) clearInterval(this._cleanupTimer)
  }
}

export default new StorageService()
