/**
 * ring-buffer.js — 环形缓冲区
 *
 * 缓存最近 N 个 IMU 采样点，支持滑动窗口提取和回溯读取。
 * 默认容量 500 点（10秒 @50Hz）。
 *
 * @module ai/ring-buffer
 */

class RingBuffer {
  /**
   * @param {number} capacity - 缓冲区容量（采样点数）
   */
  constructor(capacity = 500) {
    this.capacity = capacity
    this.buffer = new Array(capacity)
    this.head = 0    // 写入位置
    this.count = 0   // 当前数据量
  }

  /**
   * 写入一个采样点
   * @param {Object} sample - { timestamp, ax, ay, az, gx, gy, gz }
   */
  write(sample) {
    this.buffer[this.head] = sample
    this.head = (this.head + 1) % this.capacity
    if (this.count < this.capacity) this.count++
  }

  /**
   * 获取最近 windowSize 个采样点（滑动窗口）
   * @param {number} windowSize - 窗口大小
   * @returns {Array|null} 窗口数据，不足时返回 null
   */
  getWindow(windowSize) {
    if (this.count < windowSize) return null

    const start = (this.head - windowSize + this.capacity) % this.capacity
    const result = []
    for (let i = 0; i < windowSize; i++) {
      result.push(this.buffer[(start + i) % this.capacity])
    }
    return result
  }

  /**
   * 回溯读取最近 n 个采样点（用于动态模式上下文）
   * @param {number} n - 回溯点数
   * @returns {Array}
   */
  lookBack(n) {
    const size = Math.min(n, this.count)
    const result = []
    for (let i = 0; i < size; i++) {
      const idx = (this.head - size + i + this.capacity) % this.capacity
      result.push(this.buffer[idx])
    }
    return result
  }

  /**
   * 清空缓冲区
   */
  clear() {
    this.head = 0
    this.count = 0
  }

  /**
   * 当前数据量
   */
  get length() {
    return this.count
  }
}

export { RingBuffer }

/**
 * sensor-hal.js — 传感器硬件抽象层
 *
 * 封装 OpenVela system.sensor 调用，提供统一的 IMU 数据采集接口。
 * 支持真实传感器和 Mock 模式切换。
 *
 * @module sensors/sensor-hal
 */

import sensor from '@system.sensor'

const SENSOR_TYPE = {
  ACCEL: 'accelerometer',
  GYRO: 'gyroscope',
}

const DEFAULT_CONFIG = {
  sampleRate: 50,       // Hz
  accelRange: 8,        // g
  gyroRange: 500,       // dps
}

class SensorHAL {
  constructor() {
    this._config = { ...DEFAULT_CONFIG }
    this._accelSubId = null
    this._gyroSubId = null
    this._accelCallback = null
    this._gyroCallback = null
    this._isRunning = false
  }

  /**
   * 配置传感器参数
   * @param {Object} config
   */
  configure(config) {
    Object.assign(this._config, config)
  }

  /**
   * 启动 IMU 采集
   * @param {Function} onData - (sample: {timestamp, ax, ay, az, gx, gy, gz}) => void
   */
  start(onData) {
    if (this._isRunning) return

    this._isRunning = true
    const interval = Math.round(1000 / this._config.sampleRate)

    // 加速度计
    sensor.subscribe({
      type: SENSOR_TYPE.ACCEL,
      interval: interval,
      callback: (data) => {
        if (this._accelCallback) this._accelCallback(data)
      },
    })

    // 陀螺仪
    sensor.subscribe({
      type: SENSOR_TYPE.GYRO,
      interval: interval,
      callback: (data) => {
        if (this._gyroCallback) this._gyroCallback(data)
      },
    })

    // 数据合并
    let accelData = null
    let gyroData = null

    this._accelCallback = (data) => {
      accelData = data
      if (gyroData) this._mergeAndEmit(accelData, gyroData, onData)
    }

    this._gyroCallback = (data) => {
      gyroData = data
      if (accelData) this._mergeAndEmit(accelData, gyroData, onData)
    }

    console.log(`[SensorHAL] Started, interval: ${interval}ms`)
  }

  /**
   * 停止采集
   */
  stop() {
    if (!this._isRunning) return

    sensor.unsubscribe({ type: SENSOR_TYPE.ACCEL })
    sensor.unsubscribe({ type: SENSOR_TYPE.GYRO })
    this._accelCallback = null
    this._gyroCallback = null
    this._isRunning = false
    console.log('[SensorHAL] Stopped')
  }

  /**
   * 合并加速度计和陀螺仪数据
   * @private
   */
  _mergeAndEmit(accel, gyro, onData) {
    onData({
      timestamp: Date.now(),
      ax: accel.x || 0,
      ay: accel.y || 0,
      az: accel.z || 0,
      gx: gyro.x || 0,
      gy: gyro.y || 0,
      gz: gyro.z || 0,
    })
  }

  get isRunning() {
    return this._isRunning
  }
}

export { SensorHAL, DEFAULT_CONFIG }

/**
 * imu-collector.js — IMU 数据采集器
 *
 * 统一采集加速度计+陀螺仪 6 轴数据。
 * 内置环形缓冲区，缓存最近 10 秒数据。
 * 支持真实传感器和 Mock 模式。
 *
 * @module sensors/imu-collector
 */

import { SensorHAL } from './sensor-hal'
import { RingBuffer } from '../ai/ring-buffer'

const SAMPLE_RATE = 50  // Hz
const BUFFER_DURATION = 10  // 秒
const BUFFER_SIZE = SAMPLE_RATE * BUFFER_DURATION  // 500 采样点

class IMUCollector {
  constructor() {
    /** @type {SensorHAL} */
    this._hal = new SensorHAL()

    /** @type {RingBuffer} 环形缓冲区 */
    this._buffer = new RingBuffer(BUFFER_SIZE)

    /** @type {Function|null} 数据回调 */
    this._onDataCallback = null

    /** @type {boolean} 是否使用 Mock 模式 */
    this._mockMode = false

    /** @type {Object|null} Mock 数据源 */
    this._mockSource = null

    /** @type {number|null} Mock 定时器 */
    this._mockTimer = null

    /** @type {number} 采样计数 */
    this._sampleCount = 0
  }

  /**
   * 启动 IMU 采集
   * @param {Object} [options]
   * @param {boolean} [options.mockMode=false] - Mock 模式
   * @param {Object} [options.mockSource] - Mock 数据源
   * @param {Function} [options.onData] - 数据回调
   */
  start(options = {}) {
    this._mockMode = options.mockMode || false
    this._onDataCallback = options.onData || null

    if (this._mockMode && options.mockSource) {
      this._mockSource = options.mockSource
      this._startMockStream()
    } else {
      this._startRealSensor()
    }

    console.log(`[IMUCollector] Started (mode: ${this._mockMode ? 'mock' : 'real'})`)
  }

  /**
   * 停止采集
   */
  stop() {
    if (this._mockMode) {
      this._stopMockStream()
    } else {
      this._hal.stop()
    }
    console.log('[IMUCollector] Stopped')
  }

  /**
   * 获取最近 N 个采样点的窗口
   * @param {number} windowSize - 窗口大小（默认 100 = 2秒）
   * @returns {Array|null}
   */
  getWindow(windowSize = 100) {
    return this._buffer.getWindow(windowSize)
  }

  /**
   * 回溯读取
   * @param {number} n
   * @returns {Array}
   */
  lookBack(n) {
    return this._buffer.lookBack(n)
  }

  /**
   * 清空缓冲区
   */
  clear() {
    this._buffer.clear()
    this._sampleCount = 0
  }

  /** @returns {number} 当前采样总数 */
  get sampleCount() {
    return this._sampleCount
  }

  /** @returns {number} 缓冲区数据量 */
  get bufferLength() {
    return this._buffer.length
  }

  // ── 真实传感器 ──

  _startRealSensor() {
    this._hal.configure({ sampleRate: SAMPLE_RATE })
    this._hal.start((sample) => {
      this._onSample(sample)
    })
  }

  // ── Mock 模式 ──

  _startMockStream() {
    if (!this._mockSource) return

    const interval = Math.round(1000 / SAMPLE_RATE)
    this._mockTimer = setInterval(() => {
      const sample = this._mockSource.generateSample()
      if (sample) this._onSample(sample)
    }, interval)
  }

  _stopMockStream() {
    if (this._mockTimer) {
      clearInterval(this._mockTimer)
      this._mockTimer = null
    }
  }

  // ── 内部 ──

  _onSample(sample) {
    this._buffer.write(sample)
    this._sampleCount++

    if (this._onDataCallback) {
      this._onDataCallback(sample)
    }
  }
}

export { IMUCollector, SAMPLE_RATE, BUFFER_SIZE }

/**
 * preprocessor.js — IMU 数据预处理管线
 *
 * 实现完整的数据预处理流程：
 * 1. 卡尔曼滤波 — 去除高频噪声
 * 2. 重力分离 — 转换为线性加速度
 * 3. 特征工程 — 时域+频域特征提取
 * 4. 归一化 — 标准化到统一范围
 *
 * @module ai/preprocessor
 */

/**
 * 简化的一维卡尔曼滤波器
 */
class KalmanFilter1D {
  constructor(q = 0.01, r = 0.1) {
    this.q = q  // 过程噪声
    this.r = r  // 测量噪声
    this.x = 0  // 估计值
    this.p = 1  // 估计误差
    this.k = 0  // 卡尔曼增益
  }

  /**
   * 滤波单个值
   * @param {number} measurement - 测量值
   * @returns {number} 滤波后的值
   */
  filter(measurement) {
    // 预测
    this.p += this.q

    // 更新
    this.k = this.p / (this.p + this.r)
    this.x += this.k * (measurement - this.x)
    this.p *= (1 - this.k)

    return this.x
  }

  reset() {
    this.x = 0
    this.p = 1
  }
}

/**
 * 特征向量结构
 * @typedef {Object} FeatureVector
 * @property {Object} accMean - 加速度均值 {x, y, z}
 * @property {Object} accStd  - 加速度标准差 {x, y, z}
 * @property {Object} accMin  - 加速度最小值 {x, y, z}
 * @property {Object} accMax  - 加速度最大值 {x, y, z}
 * @property {Object} gyroMean - 陀螺仪均值 {x, y, z}
 * @property {Object} gyroStd  - 陀螺仪标准差 {x, y, z}
 * @property {number} dominantFreq - 主频率 (Hz)
 * @property {number} zeroCrossRate - 过零率
 * @property {number} motionIntensity - 运动强度
 */

class Preprocessor {
  constructor() {
    // 卡尔曼滤波器（每轴一个）
    this._kfAx = new KalmanFilter1D()
    this._kfAy = new KalmanFilter1D()
    this._kfAz = new KalmanFilter1D()
    this._kfGx = new KalmanFilter1D()
    this._kfGy = new KalmanFilter1D()
    this._kfGz = new KalmanFilter1D()

    // 重力估计（低通滤波）
    this._gravity = { x: 0, y: 0, z: -9.8 }
    this._gravityAlpha = 0.02  // 低通系数

    // 归一化参数
    this._accelRange = 2 * 9.8   // ±2g
    this._gyroRange = 250 * Math.PI / 180  // ±250dps -> rad/s
  }

  /**
   * 预处理一个采样窗口
   * @param {Array} window - 采样点数组 [{timestamp, ax, ay, az, gx, gy, gz}, ...]
   * @returns {FeatureVector|null} 特征向量，窗口不足时返回 null
   */
  processWindow(window) {
    if (!window || window.length < 10) return null

    const n = window.length

    // 1. 卡尔曼滤波 + 重力分离
    const filtered = []
    for (let i = 0; i < n; i++) {
      const s = window[i]
      const ax = this._kfAx.filter(s.ax)
      const ay = this._kfAy.filter(s.ay)
      const az = this._kfAz.filter(s.az)
      const gx = this._kfGx.filter(s.gx)
      const gy = this._kfGy.filter(s.gy)
      const gz = this._kfGz.filter(s.gz)

      // 重力分离（低通滤波估计重力分量）
      this._gravity.x += this._gravityAlpha * (ax - this._gravity.x)
      this._gravity.y += this._gravityAlpha * (ay - this._gravity.y)
      this._gravity.z += this._gravityAlpha * (az - this._gravity.z)

      // 线性加速度 = 原始加速度 - 重力
      filtered.push({
        ax: ax - this._gravity.x,
        ay: ay - this._gravity.y,
        az: az - this._gravity.z,
        gx: gx,
        gy: gy,
        gz: gz,
      })
    }

    // 2. 时域特征提取
    const accMean = this._calcMean(filtered, 'a')
    const accStd = this._calcStd(filtered, 'a', accMean)
    const accMin = this._calcMin(filtered, 'a')
    const accMax = this._calcMax(filtered, 'a')
    const gyroMean = this._calcMean(filtered, 'g')
    const gyroStd = this._calcStd(filtered, 'g', gyroMean)

    // 3. 频域特征（Z轴FFT主频率）
    const azValues = filtered.map(f => f.az)
    const dominantFreq = this._calcDominantFreq(azValues)

    // 4. 过零率
    const zeroCrossRate = this._calcZeroCrossRate(azValues)

    // 5. 运动强度
    const motionIntensity = this._calcMotionIntensity(accStd)

    return {
      accMean,
      accStd,
      accMin,
      accMax,
      gyroMean,
      gyroStd,
      dominantFreq,
      zeroCrossRate,
      motionIntensity,
    }
  }

  /**
   * 将特征向量转换为模型输入张量
   * @param {FeatureVector} features
   * @returns {Array} 一维数组，可直接输入模型
   */
  toTensor(features) {
    if (!features) return null

    return [
      // 加速度均值 (3)
      features.accMean.x, features.accMean.y, features.accMean.z,
      // 加速度标准差 (3)
      features.accStd.x, features.accStd.y, features.accStd.z,
      // 加速度极值 (6)
      features.accMin.x, features.accMin.y, features.accMin.z,
      features.accMax.x, features.accMax.y, features.accMax.z,
      // 陀螺仪均值 (3)
      features.gyroMean.x, features.gyroMean.y, features.gyroMean.z,
      // 陀螺仪标准差 (3)
      features.gyroStd.x, features.gyroStd.y, features.gyroStd.z,
      // 频域+统计 (3)
      features.dominantFreq,
      features.zeroCrossRate,
      features.motionIntensity,
    ]
  }

  /**
   * 重置滤波器状态
   */
  reset() {
    this._kfAx.reset()
    this._kfAy.reset()
    this._kfAz.reset()
    this._kfGx.reset()
    this._kfGy.reset()
    this._kfGz.reset()
    this._gravity = { x: 0, y: 0, z: -9.8 }
  }

  // ── 统计计算 ──

  _calcMean(data, prefix) {
    const key = prefix + 'x'
    let sx = 0, sy = 0, sz = 0
    const n = data.length
    for (let i = 0; i < n; i++) {
      sx += data[i][prefix + 'x']
      sy += data[i][prefix + 'y']
      sz += data[i][prefix + 'z']
    }
    return { x: sx / n, y: sy / n, z: sz / n }
  }

  _calcStd(data, prefix, mean) {
    let sx = 0, sy = 0, sz = 0
    const n = data.length
    for (let i = 0; i < n; i++) {
      const dx = data[i][prefix + 'x'] - mean.x
      const dy = data[i][prefix + 'y'] - mean.y
      const dz = data[i][prefix + 'z'] - mean.z
      sx += dx * dx
      sy += dy * dy
      sz += dz * dz
    }
    return {
      x: Math.sqrt(sx / n),
      y: Math.sqrt(sy / n),
      z: Math.sqrt(sz / n),
    }
  }

  _calcMin(data, prefix) {
    let mx = Infinity, my = Infinity, mz = Infinity
    for (let i = 0; i < data.length; i++) {
      if (data[i][prefix + 'x'] < mx) mx = data[i][prefix + 'x']
      if (data[i][prefix + 'y'] < my) my = data[i][prefix + 'y']
      if (data[i][prefix + 'z'] < mz) mz = data[i][prefix + 'z']
    }
    return { x: mx, y: my, z: mz }
  }

  _calcMax(data, prefix) {
    let mx = -Infinity, my = -Infinity, mz = -Infinity
    for (let i = 0; i < data.length; i++) {
      if (data[i][prefix + 'x'] > mx) mx = data[i][prefix + 'x']
      if (data[i][prefix + 'y'] > my) my = data[i][prefix + 'y']
      if (data[i][prefix + 'z'] > mz) mz = data[i][prefix + 'z']
    }
    return { x: mx, y: my, z: mz }
  }

  /**
   * 简化 FFT 主频率检测
   * @private
   */
  _calcDominantFreq(signal) {
    const n = signal.length
    if (n < 2) return 0

    // 简化版：用过零率近似主频率
    let crossings = 0
    const mean = signal.reduce((a, b) => a + b, 0) / n
    for (let i = 1; i < n; i++) {
      if ((signal[i - 1] - mean) * (signal[i] - mean) < 0) crossings++
    }

    return crossings / (2 * n) * 50  // 采样率 50Hz
  }

  /**
   * 过零率
   * @private
   */
  _calcZeroCrossRate(signal) {
    let crossings = 0
    for (let i = 1; i < signal.length; i++) {
      if (signal[i - 1] * signal[i] < 0) crossings++
    }
    return crossings / (signal.length - 1)
  }

  /**
   * 运动强度（加速度标准差的模）
   * @private
   */
  _calcMotionIntensity(accStd) {
    return Math.sqrt(accStd.x * accStd.x + accStd.y * accStd.y + accStd.z * accStd.z)
  }
}

