/**
 * inference-scheduler.js — 推理调度器
 *
 * 自适应推理频率控制：
 * - 静止状态：每 5 秒推理 1 次
 * - 活动状态：每秒推理 1 次
 * - 基于加速度方差判断运动强度
 * - 状态切换时触发回调
 *
 * @module ai/inference-scheduler
 */

const MOTION_THRESHOLD = 0.5   // 运动强度阈值
const STATIC_INTERVAL = 5000   // 静止推理间隔 (ms)
const ACTIVE_INTERVAL = 1000   // 活动推理间隔 (ms)
const WINDOW_SIZE = 100        // 滑动窗口大小（采样点数）

class InferenceScheduler {
  constructor() {
    /** @type {Object|null} 模型实例 */
    this._model = null

    /** @type {Object|null} 预处理器 */
    this._preprocessor = null

    /** @type {Object|null} IMU 采集器 */
    this._collector = null

    /** @type {Function|null} 结果回调 */
    this._onResult = null

    /** @type {Function|null} 状态切换回调 */
    this._onStateChange = null

    /** @type {number|null} 推理定时器 */
    this._timer = null

    /** @type {boolean} 是否运行中 */
    this._running = false

    /** @type {string} 当前运动状态 */
    this._motionState = 'static'  // 'static' | 'active'

    /** @type {number} 上次推理时间 */
    this._lastInferTime = 0

    /** @type {number} 当前推理间隔 */
    this._currentInterval = STATIC_INTERVAL

    /** @type {number} 数据计数 */
    this._dataCount = 0
  }

  /**
   * 启动推理调度
   * @param {Object} options
   * @param {Object} options.model - 模型实例
   * @param {Object} options.preprocessor - 预处理器
   * @param {Object} options.collector - IMU 采集器
   * @param {Function} options.onResult - 结果回调
   * @param {Function} [options.onStateChange] - 状态切换回调
   */
  start(options) {
    if (this._running) return

    this._model = options.model
    this._preprocessor = options.preprocessor
    this._collector = options.collector
    this._onResult = options.onResult || null
    this._onStateChange = options.onStateChange || null
    this._running = true
    this._dataCount = 0

    // 启动自适应定时推理
    this._scheduleNext()

    console.log('[InferenceScheduler] Started')
  }

  /**
   * 停止推理调度
   */
  stop() {
    if (!this._running) return

    if (this._timer) {
      clearTimeout(this._timer)
      this._timer = null
    }

    this._running = false
    this._model = null
    this._preprocessor = null
    this._collector = null

    console.log('[InferenceScheduler] Stopped')
  }

  /**
   * 通知有新数据到达
   * @param {Object} sample - 采样点
   */
  onNewData(sample) {
    if (!this._running) return

    this._dataCount++

    // 每 50 个采样点（1秒）评估一次运动状态
    if (this._dataCount % 50 === 0) {
      this._evaluateMotionState()
    }
  }

  /**
   * 评估运动状态并调整推理频率
   * @private
   */
  _evaluateMotionState() {
    if (!this._collector) return

    // 获取最近 1 秒的数据窗口
    const window = this._collector.getWindow(50)
    if (!window || window.length < 10) return

    // 计算加速度标准差作为运动强度指标
    let sx = 0, sy = 0, sz = 0
    const n = window.length
    let axSum = 0, aySum = 0, azSum = 0

    for (let i = 0; i < n; i++) {
      axSum += window[i].ax
      aySum += window[i].ay
      azSum += window[i].az
    }

    const axMean = axSum / n
    const ayMean = aySum / n
    const azMean = azSum / n

    for (let i = 0; i < n; i++) {
      const dx = window[i].ax - axMean
      const dy = window[i].ay - ayMean
      const dz = window[i].az - azMean
      sx += dx * dx
      sy += dy * dy
      sz += dz * dz
    }

    const intensity = Math.sqrt(
      (sx + sy + sz) / (n * 3)
    )

    // 判断运动状态
    const newState = intensity > MOTION_THRESHOLD ? 'active' : 'static'

    // 状态切换
    if (newState !== this._motionState) {
      this._motionState = newState
      this._currentInterval = newState === 'active' ? ACTIVE_INTERVAL : STATIC_INTERVAL

      if (this._onStateChange) {
        this._onStateChange(newState)
      }

      console.log(`[InferenceScheduler] State: ${newState}, interval: ${this._currentInterval}ms`)
    }
  }

  /**
   * 调度下次推理
   * @private
   */
  _scheduleNext() {
    if (!this._running) return

    this._timer = setTimeout(() => {
      this._runInference()
      this._scheduleNext()
    }, this._currentInterval)
  }

  /**
   * 执行一次推理
   * @private
   */
  _runInference() {
    if (!this._model || !this._preprocessor || !this._collector) return

    // 获取滑动窗口
    const window = this._collector.getWindow(WINDOW_SIZE)
    if (!window) return  // 数据不足

    // 预处理
    const features = this._preprocessor.processWindow(window)
    if (!features) return

    // 转换为张量
    const tensor = this._preprocessor.toTensor(features)
    if (!tensor) return

    // 推理
    const output = this._model.infer(tensor)
    if (!output) return

    // 后处理
    const result = this._model.postprocess(output, 'classification')
    if (result && this._onResult) {
      this._onResult(result)
    }

    this._lastInferTime = Date.now()
  }
}

export { InferenceScheduler, MOTION_THRESHOLD, STATIC_INTERVAL, ACTIVE_INTERVAL }

/**
 * data-store.js — KVDB 数据存储
 *
 * 基于 system.storage 的体态数据存储。
 * 存储体态历史记录和每日统计数据。
 *
 * @module storage/data-store
 */

import storage from '@system.storage'

const STORAGE_KEYS = {
  DAILY_STATS: 'pose_daily_stats',      // 每日统计
  HISTORY: 'pose_history',              // 体态历史（最近 7 天）
  SETTINGS: 'pose_settings',           // 用户设置
  CURRENT_SESSION: 'pose_session',      // 当前会话数据
}

class DataStore {
  constructor() {
    this._cache = {}
  }

  /**
   * 初始化存储
   * @returns {Promise<void>}
   */
  async init() {
    // 加载缓存
    for (const [key, value] of Object.entries(STORAGE_KEYS)) {
      try {
        const data = await this._get(value)
        this._cache[value] = data ? JSON.parse(data) : null
      } catch (e) {
        this._cache[value] = null
      }
    }
    console.log('[DataStore] Initialized')
  }

  /**
   * 记录一次体态识别结果
   * @param {Object} result - { pose, confidence, timestamp }
   */
  async recordPosture(result) {
    const today = this._getTodayKey()

    // 更新当前会话
    if (!this._cache[STORAGE_KEYS.CURRENT_SESSION]) {
      this._cache[STORAGE_KEYS.CURRENT_SESSION] = {
        date: today,
        records: [],
        summary: {},
      }
    }

    const session = this._cache[STORAGE_KEYS.CURRENT_SESSION]
    session.records.push({
      pose: result.pose,
      confidence: result.confidence,
      timestamp: result.timestamp || Date.now(),
    })

    // 限制会话记录数
    if (session.records.length > 10000) {
      session.records = session.records.slice(-5000)
    }

    // 更新每日统计
    this._updateDailyStats(today, result)

    // 异步持久化（不阻塞）
    this._persistSession()
  }

  /**
   * 获取每日统计
   * @param {string} [date] - 日期 key，默认今天
   * @returns {Object} { date, total, distribution: {pose: count}, avgConfidence }
   */
  async getDailyStats(date) {
    const key = date || this._getTodayKey()
    const stats = this._cache[STORAGE_KEYS.DAILY_STATS]
    return stats && stats[key] ? stats[key] : {
      date: key,
      total: 0,
      distribution: {},
      avgConfidence: 0,
    }
  }

  /**
   * 获取最近 N 天的统计
   * @param {number} days - 天数
   * @returns {Array}
   */
  async getWeeklyStats(days = 7) {
    const stats = this._cache[STORAGE_KEYS.DAILY_STATS] || {}
    const result = []

    for (let i = days - 1; i >= 0; i--) {
      const d = new Date()
      d.setDate(d.getDate() - i)
      const key = this._formatDate(d)
      result.push(stats[key] || {
        date: key,
        total: 0,
        distribution: {},
        avgConfidence: 0,
      })
    }

    return result
  }

  /**
   * 获取当前会话记录
   * @returns {Array}
   */
  getSessionRecords() {
    const session = this._cache[STORAGE_KEYS.CURRENT_SESSION]
    return session ? session.records : []
  }

  /**
   * 清除当前会话
   */
  async clearSession() {
    this._cache[STORAGE_KEYS.CURRENT_SESSION] = null
    await this._remove(STORAGE_KEYS.CURRENT_SESSION)
  }

  /**
   * 获取所有设置
   * @returns {Object}
   */
  async getSettings() {
    const data = await this._get(STORAGE_KEYS.SETTINGS)
    return data ? JSON.parse(data) : {
      sensitivity: 'medium',
      samplingRate: 50,
      retentionDays: 30,
      modelType: 'static_cnn',
    }
  }

  /**
   * 保存设置
   * @param {Object} settings
   */
  async saveSettings(settings) {
    await this._set(STORAGE_KEYS.SETTINGS, JSON.stringify(settings))
  }

  // ── 内部方法 ──

  _updateDailyStats(today, result) {
    if (!this._cache[STORAGE_KEYS.DAILY_STATS]) {
      this._cache[STORAGE_KEYS.DAILY_STATS] = {}
    }

    const stats = this._cache[STORAGE_KEYS.DAILY_STATS]
    if (!stats[today]) {
      stats[today] = { date: today, total: 0, distribution: {}, avgConfidence: 0 }
    }

    const day = stats[today]
    day.total++
    day.distribution[result.pose] = (day.distribution[result.pose] || 0) + 1
    day.avgConfidence = (day.avgConfidence * (day.total - 1) + result.confidence) / day.total
  }

  _getTodayKey() {
    return this._formatDate(new Date())
  }

  _formatDate(d) {
    const y = d.getFullYear()
    const m = String(d.getMonth() + 1).padStart(2, '0')
    const day = String(d.getDate()).padStart(2, '0')
    return `${y}-${m}-${day}`
  }

  async _persistSession() {
    try {
      const session = this._cache[STORAGE_KEYS.CURRENT_SESSION]
      if (session) {
        await this._set(STORAGE_KEYS.CURRENT_SESSION, JSON.stringify(session))
      }
      // 同时持久化统计
      const stats = this._cache[STORAGE_KEYS.DAILY_STATS]
      if (stats) {
        await this._set(STORAGE_KEYS.DAILY_STATS, JSON.stringify(stats))
      }
    } catch (e) {
      console.error('[DataStore] Persist failed:', e)
    }
  }

  _get(key) {
    return new Promise((resolve, reject) => {
      storage.get({
        key,
        success: (data) => resolve(data),
        fail: () => resolve(null),
      })
    })
  }

  _set(key, value) {
    return new Promise((resolve, reject) => {
      storage.set({
        key,
        value,
        success: () => resolve(),
        fail: (err) => reject(err),
      })
    })
  }

  _remove(key) {
    return new Promise((resolve) => {
      storage.delete({
        key,
        success: () => resolve(),
        fail: () => resolve(),
      })
    })
  }
}

export { DataStore, STORAGE_KEYS }

/**
 * power-manager.js — 功耗管理
 *
 * 动态调节传感器采样率和推理频率，优化电池续航。
 * 静止状态降低采样率，活动状态恢复高频采样。
 *
 * @module power/power-manager
 */

const POWER_MODE = {
  LOW: 'low',       // 低功耗：10Hz 采样，5秒推理
  NORMAL: 'normal', // 正常：50Hz 采样，1秒推理
  HIGH: 'high',     // 高性能：50Hz 采样，500ms推理（预留动态阶段）
}

const MODE_CONFIG = {
  [POWER_MODE.LOW]: {
    sampleRate: 10,
    inferInterval: 5000,
    description: '低功耗模式',
  },
  [POWER_MODE.NORMAL]: {
    sampleRate: 50,
    inferInterval: 1000,
    description: '正常模式',
  },
  [POWER_MODE.HIGH]: {
    sampleRate: 50,
    inferInterval: 500,
    description: '高性能模式',
  },
}

class PowerManager {
  constructor() {
    /** @type {string} 当前功耗模式 */
    this._currentMode = POWER_MODE.NORMAL

    /** @type {Object} 模式配置 */
    this._config = { ...MODE_CONFIG }

    /** @type {Function|null} 模式切换回调 */
    this._onModeChange = null

    /** @type {boolean} 是否启用自适应 */
    this._adaptiveEnabled = true

    /** @type {number} 连续静止计数 */
    this._staticCount = 0

    /** @type {number} 连续活动计数 */
    this._activeCount = 0

    /** @type {number} 切换阈值 */
    this._switchThreshold = 3
  }

  /**
   * 根据运动状态调整功耗模式
   * @param {string} motionState - 'static' | 'active'
   */
  adjustForMotion(motionState) {
    if (!this._adaptiveEnabled) return

    if (motionState === 'static') {
      this._staticCount++
      this._activeCount = 0

      if (this._staticCount >= this._switchThreshold && this._currentMode !== POWER_MODE.LOW) {
        this.setMode(POWER_MODE.LOW)
      }
    } else {
      this._activeCount++
      this._staticCount = 0

      if (this._activeCount >= this._switchThreshold && this._currentMode !== POWER_MODE.NORMAL) {
        this.setMode(POWER_MODE.NORMAL)
      }
    }
  }

  /**
   * 设置功耗模式
   * @param {string} mode
   */
  setMode(mode) {
    if (mode === this._currentMode) return

    const oldMode = this._currentMode
    this._currentMode = mode

    if (this._onModeChange) {
      this._onModeChange(mode, oldMode)
    }

    console.log(`[PowerManager] Mode: ${oldMode} → ${mode} (${this._config[mode].description})`)
  }

  /**
   * 启用/禁用自适应功耗
   * @param {boolean} enabled
   */
  setAdaptive(enabled) {
    this._adaptiveEnabled = enabled
    if (!enabled) {
      this.setMode(POWER_MODE.NORMAL)
    }
  }

  /**
   * 设置模式切换回调
   * @param {Function} callback - (newMode, oldMode) => void
   */
  onModeChange(callback) {
    this._onModeChange = callback
  }

  /**
   * 获取当前配置
   * @returns {Object} { sampleRate, inferInterval, description }
   */
  getCurrentConfig() {
    return { ...this._config[this._currentMode] }
  }

  /** @returns {string} 当前功耗模式 */
  get currentMode() {
    return this._currentMode
  }

  /** @returns {boolean} 是否自适应启用 */
  get isAdaptive() {
    return this._adaptiveEnabled
  }
}

export { PowerManager, POWER_MODE, MODE_CONFIG }

/**
 * imu-scenarios.js — 7 类体态 IMU 模拟数据
 *
 * 为每种体态生成特征鲜明的 IMU 模拟数据。
 * 每个场景包含 5 秒的循环数据序列（250 采样点 @50Hz）。
 *
 * @module mock/imu-scenarios
 */

/**
 * 体态类型枚举
 */
const POSE_TYPE = {
  STANDARD_SIT: 'standard_sit',
  HUNCHED_SIT: 'hunched_sit',
  STANDARD_STAND: 'standard_stand',
  WALKING: 'walking',
  RUNNING: 'running',
  STILL: 'still',
  UNKNOWN: 'unknown',
}

/**
 * 场景配置：每种体态的 IMU 数据特征
 * ax/ay/az: 加速度 (m/s²)，静止时 az ≈ -9.8
 * gx/gy/gz: 陀螺仪角速度 (rad/s)
 */
const SCENE_CONFIG = {
  // 标准坐姿：轻微晃动，z轴稳定
  [POSE_TYPE.STANDARD_SIT]: {
    ax: { mean: 0.1, noise: 0.05 },
    ay: { mean: 0.0, noise: 0.03 },
    az: { mean: -9.75, noise: 0.02 },
    gx: { mean: 0.0, noise: 0.01 },
    gy: { mean: 0.0, noise: 0.01 },
    gz: { mean: 0.0, noise: 0.005 },
  },

  // 驼背坐姿：z轴偏移，前倾特征
  [POSE_TYPE.HUNCHED_SIT]: {
    ax: { mean: 0.8, noise: 0.1 },     // 前倾
    ay: { mean: 0.0, noise: 0.05 },
    az: { mean: -9.5, noise: 0.05 },   // z轴偏小（倾斜）
    gx: { mean: -0.1, noise: 0.02 },   // 轻微前倾角速度
    gy: { mean: 0.0, noise: 0.01 },
    gz: { mean: 0.0, noise: 0.01 },
  },

  // 标准站姿：z轴稳定，微小晃动
  [POSE_TYPE.STANDARD_STAND]: {
    ax: { mean: 0.0, noise: 0.03 },
    ay: { mean: 0.0, noise: 0.03 },
    az: { mean: -9.8, noise: 0.02 },
    gx: { mean: 0.0, noise: 0.008 },
    gy: { mean: 0.0, noise: 0.008 },
    gz: { mean: 0.0, noise: 0.005 },
  },

  // 行走：周期性加速度波动
  [POSE_TYPE.WALKING]: {
    ax: { mean: 0.0, noise: 0.8, pattern: 'sine', freq: 2.0, amp: 0.6 },
    ay: { mean: 0.0, noise: 0.3, pattern: 'sine', freq: 2.0, amp: 0.2 },
    az: { mean: -9.8, noise: 0.5, pattern: 'sine', freq: 2.0, amp: 0.4 },
    gx: { mean: 0.0, noise: 0.15, pattern: 'sine', freq: 2.0, amp: 0.1 },
    gy: { mean: 0.0, noise: 0.1, pattern: 'sine', freq: 2.0, amp: 0.08 },
    gz: { mean: 0.0, noise: 0.05 },
  },

  // 跑步：高频大幅波动
  [POSE_TYPE.RUNNING]: {
    ax: { mean: 0.0, noise: 1.5, pattern: 'sine', freq: 3.0, amp: 1.2 },
    ay: { mean: 0.0, noise: 0.8, pattern: 'sine', freq: 3.0, amp: 0.5 },
    az: { mean: -9.8, noise: 2.0, pattern: 'sine', freq: 3.0, amp: 1.5 },
    gx: { mean: 0.0, noise: 0.3, pattern: 'sine', freq: 3.0, amp: 0.2 },
    gy: { mean: 0.0, noise: 0.2, pattern: 'sine', freq: 3.0, amp: 0.15 },
    gz: { mean: 0.0, noise: 0.1 },
  },

  // 静止/躺卧：几乎无波动
  [POSE_TYPE.STILL]: {
    ax: { mean: 0.0, noise: 0.01 },
    ay: { mean: 0.0, noise: 0.01 },
    az: { mean: -9.81, noise: 0.005 },
    gx: { mean: 0.0, noise: 0.002 },
    gy: { mean: 0.0, noise: 0.002 },
    gz: { mean: 0.0, noise: 0.001 },
  },

  // 未知/过渡：不规则波动
  [POSE_TYPE.UNKNOWN]: {
    ax: { mean: 0.5, noise: 0.5, pattern: 'random' },
    ay: { mean: 0.3, noise: 0.4, pattern: 'random' },
    az: { mean: -9.5, noise: 0.8, pattern: 'random' },
    gx: { mean: 0.1, noise: 0.2, pattern: 'random' },
    gy: { mean: 0.05, noise: 0.15, pattern: 'random' },
    gz: { mean: 0.02, noise: 0.1, pattern: 'random' },
  },
}

/**
 * IMU 数据生成器
 */
class IMUScenarioGenerator {
  /**
   * @param {string} scenarioType - 体态类型
   * @param {Object} [options]
   * @param {number} [options.sampleRate=50] - 采样率
   * @param {number} [options.duration=5] - 循环时长（秒）
   */
  constructor(scenarioType, options = {}) {
    this._type = scenarioType
    this._sampleRate = options.sampleRate || 50
    this._duration = options.duration || 5
    this._totalSamples = this._sampleRate * this._duration
    this._sampleIndex = 0

    this._config = SCENE_CONFIG[scenarioType] || SCENE_CONFIG[POSE_TYPE.UNKNOWN]
  }

  /**
   * 生成下一个采样点
   * @returns {Object} { timestamp, ax, ay, az, gx, gy, gz }
   */
  generateSample() {
    const t = this._sampleIndex / this._sampleRate
    const sample = {
      timestamp: Date.now(),
    }

    for (const axis of ['ax', 'ay', 'az', 'gx', 'gy', 'gz']) {
      const cfg = this._config[axis]
      let value = cfg.mean

      // 正弦模式（行走/跑步）
      if (cfg.pattern === 'sine') {
        value += cfg.amp * Math.sin(2 * Math.PI * cfg.freq * t)
      }

      // 添加噪声
      value += (Math.random() - 0.5) * 2 * cfg.noise

      sample[axis] = value
    }

    this._sampleIndex = (this._sampleIndex + 1) % this._totalSamples
    return sample
  }

  /**
   * 重置到序列开头
   */
  reset() {
    this._sampleIndex = 0
  }

  /** @returns {string} 场景类型 */
  get type() {
    return this._type
  }
}

/**
 * 混合场景生成器
 * 按时间比例混合多种体态
 */
class MixedScenarioGenerator {
  /**
   * @param {Array} segments - [{ type, duration }, ...]
   * @param {Object} [options]
   */
  constructor(segments, options = {}) {
    this._segments = segments
    this._sampleRate = options.sampleRate || 50

    // 预计算每段的采样数
    this._segmentSamples = segments.map(s => s.duration * this._sampleRate)
    this._totalSamples = this._segmentSamples.reduce((a, b) => a + b, 0)

    // 为每段创建生成器
    this._generators = segments.map(s => new IMUScenarioGenerator(s.type, { sampleRate: this._sampleRate }))

    this._currentSegment = 0
    this._segmentIndex = 0
  }

  /**
   * 生成下一个采样点
   * @returns {Object}
   */
  generateSample() {
    if (this._currentSegment >= this._generators.length) {
      // 循环回到第一段
      this._currentSegment = 0
      this._segmentIndex = 0
      this._generators.forEach(g => g.reset())
    }

    const sample = this._generators[this._currentSegment].generateSample()
    this._segmentIndex++

    // 切换到下一段
    if (this._segmentIndex >= this._segmentSamples[this._currentSegment]) {
      this._currentSegment++
      this._segmentIndex = 0
    }

    return sample
  }

  /** @returns {string} 当前段的体态类型 */
  get currentType() {
    if (this._currentSegment < this._segments.length) {
      return this._segments[this._currentSegment].type
    }
    return POSE_TYPE.UNKNOWN
  }
}

// ── 预定义场景 ──

const PRESET_SCENARIOS = {
  // 坐姿办公 1 小时
  'office-1h': () => new MixedScenarioGenerator([
    { type: POSE_TYPE.STANDARD_SIT, duration: 60 },
    { type: POSE_TYPE.HUNCHED_SIT, duration: 40 },
    { type: POSE_TYPE.WALKING, duration: 10 },
    { type: POSE_TYPE.STANDARD_SIT, duration: 50 },
    { type: POSE_TYPE.HUNCHED_SIT, duration: 30 },
    { type: POSE_TYPE.WALKING, duration: 5 },
    { type: POSE_TYPE.STANDARD_SIT, duration: 35 },
  ]),

  // 久坐 2 小时
  'sedentary-2h': () => new MixedScenarioGenerator([
    { type: POSE_TYPE.STANDARD_SIT, duration: 120 },
    { type: POSE_TYPE.HUNCHED_SIT, duration: 80 },
    { type: POSE_TYPE.STILL, duration: 20 },
  ]),

  // 混合日常
  'mixed-daily': () => new MixedScenarioGenerator([
    { type: POSE_TYPE.STANDARD_SIT, duration: 60 },
    { type: POSE_TYPE.WALKING, duration: 20 },
    { type: POSE_TYPE.STANDARD_STAND, duration: 15 },
    { type: POSE_TYPE.HUNCHED_SIT, duration: 45 },
    { type: POSE_TYPE.RUNNING, duration: 10 },
    { type: POSE_TYPE.STILL, duration: 30 },
    { type: POSE_TYPE.WALKING, duration: 20 },
  ]),

  // 运动跑步
  'running-session': () => new MixedScenarioGenerator([
    { type: POSE_TYPE.STANDARD_STAND, duration: 10 },
    { type: POSE_TYPE.WALKING, duration: 20 },
    { type: POSE_TYPE.RUNNING, duration: 60 },
    { type: POSE_TYPE.WALKING, duration: 15 },
    { type: POSE_TYPE.STILL, duration: 15 },
  ]),
}

export {
  POSE_TYPE,
  SCENE_CONFIG,
  IMUScenarioGenerator,
  MixedScenarioGenerator,
  PRESET_SCENARIOS,
}

